    {
      "source_qa_id": "mythology_systems__major_deities__011__neighbor__norse_major_deities_2__en__surface_002",
      "language": "zh",
      "question": "请说出被描述为身旁有乌鸦相伴的北欧主要神明的名字。",
      "expected_answer": "奥丁",
      "answer_aliases": [
        "Óðinn"
      ],
      "translation_note": "Rephrased as an imperative command."
    },
    {
      "source_qa_id": "mythology_systems__major_deities__011__neighbor__norse_major_deities_2__en__surface_003",
      "language": "zh",
      "question": "在北欧神话中，哪位主要神明以身旁有乌鸦相伴而闻名？",
      "expected_answer": "奥丁",
      "answer_aliases": [
        "Óðinn"
